import{_ as a,c as s,o as t,ag as i}from"./chunks/framework.Ds6Eueu6.js";const u=JSON.parse('{"title":"Docker","description":"","frontmatter":{},"headers":[],"relativePath":"master/installation/docker.md","filePath":"master/installation/docker.md","lastUpdated":1786447935000}'),o={name:"master/installation/docker.md"};function n(r,e,l,p,d,c){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><a href="https://www.docker.com/" target="_blank" rel="noreferrer">Docker</a> is an open platform for developing, shipping, and running applications. Docker enables you to separate your applications from your infrastructure so you can deliver software quickly. AureusERP ships as a single-container production image, so a plain <code>docker run</code> is all it takes — Docker Compose is only used for local development via Laravel Sail.</p><h3 id="database-and-storage-persistence" tabindex="-1">Database and Storage Persistence <a class="header-anchor" href="#database-and-storage-persistence" aria-label="Permalink to &quot;Database and Storage Persistence&quot;">​</a></h3><p>It is recommended to attach named volumes for the database data directory and the application storage directory. This ensures that your data persists even in the case of container failure or termination — even if you destroy the container, your data won&#39;t be lost unless you remove the volumes explicitly.</p><h2 id="docker-setup-for-aureuserp" tabindex="-1">Docker Setup for AureusERP <a class="header-anchor" href="#docker-setup-for-aureuserp" aria-label="Permalink to &quot;Docker Setup for AureusERP&quot;">​</a></h2><p>You can run AureusERP using the pre-configured production image from Docker Hub. It is a single-container, production-ready image that bundles the application, Nginx, PHP-FPM, MySQL, and Supervisor — everything needed to run the ERP with one <code>docker run</code>. AureusERP is fully installed at build time (migrations, seeders, roles &amp; permissions, admin user), so the container boots ready to use.</p><p>The image sources live in the <code>docker/production/</code> directory of the repository, and you can also build it yourself from there:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker/production</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Local development</p><p>The production image is meant for running AureusERP. For local development, use Laravel Sail via the <code>docker-compose.yml</code> at the repository root.</p></div><h3 id="step-1-pull-the-docker-image" tabindex="-1"><strong>Step 1: Pull the Docker Image</strong> <a class="header-anchor" href="#step-1-pull-the-docker-image" aria-label="Permalink to &quot;**Step 1: Pull the Docker Image**&quot;">​</a></h3><p>Begin by pulling the AureusERP Docker image with the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webkul/aureuserp:latest</span></span></code></pre></div><h3 id="step-2-run-the-container" tabindex="-1"><strong>Step 2: Run the Container</strong> <a class="header-anchor" href="#step-2-run-the-container" aria-label="Permalink to &quot;**Step 2: Run the Container**&quot;">​</a></h3><p>Once the image is pulled, start a new container using the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80:80</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureus-mysql:/var/lib/mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureus-storage:/var/www/aureuserp/storage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  webkul/aureuserp:latest</span></span></code></pre></div><h4 id="explanation-of-the-command" tabindex="-1">Explanation of the Command <a class="header-anchor" href="#explanation-of-the-command" aria-label="Permalink to &quot;Explanation of the Command&quot;">​</a></h4><ul><li><code>-d</code>: Runs the container in detached mode.</li><li><code>--name aureuserp</code>: Names the container &quot;aureuserp&quot; for easy reference.</li><li><code>-p 80:80</code>: Maps port 80 on the host to port 80 in the container (for web access). To use a different host port, change it, e.g. <code>-p 8080:80</code>.</li><li><code>-v aureus-mysql:/var/lib/mysql</code>: Persists the database files in a named volume.</li><li><code>-v aureus-storage:/var/www/aureuserp/storage</code>: Persists uploads, logs, and app state.</li><li><code>webkul/aureuserp:latest</code>: Specifies the latest AureusERP Docker image.</li></ul><div class="warning custom-block"><p class="custom-block-title">Persistence</p><p>Without the named volumes the container is ephemeral — all data is lost on <code>docker rm</code>. Use named volumes (not bind mounts), as an empty bind mount would shadow the pre-installed data. Never expose the MySQL port 3306 publicly.</p></div><div class="tip custom-block"><p class="custom-block-title">Local testing over plain HTTP</p><p>The image defaults to <code>APP_ENV=production</code>, which forces every generated URL to <code>https</code> — correct for a live site behind TLS. For local testing over plain HTTP, run with <code>-e APP_ENV=local -e APP_URL=http://localhost</code>. The image has no built-in TLS — terminate HTTPS at a reverse proxy in front of the container.</p></div><p>You can override application and database settings at runtime with environment variables such as <code>APP_URL</code>, <code>APP_NAME</code>, <code>APP_TIMEZONE</code>, <code>APP_LOCALE</code>, <code>APP_CURRENCY</code>, and <code>DB_HOST</code>, <code>DB_PORT</code>, <code>DB_DATABASE</code>, <code>DB_USERNAME</code>, <code>DB_PASSWORD</code>. Setting <code>DB_HOST</code> to a non-local address switches the container to an external MySQL server and keeps the internal MySQL off. See <code>docker/production/README.md</code> in the repository for the full reference.</p><h3 id="step-3-verify-the-running-container" tabindex="-1"><strong>Step 3: Verify the Running Container</strong> <a class="header-anchor" href="#step-3-verify-the-running-container" aria-label="Permalink to &quot;**Step 3: Verify the Running Container**&quot;">​</a></h3><p>To check if your container is running, use the command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p>You should see <code>aureuserp</code> in the list of active containers.</p><h3 id="step-4-access-aureuserp" tabindex="-1"><strong>Step 4: Access AureusERP</strong> <a class="header-anchor" href="#step-4-access-aureuserp" aria-label="Permalink to &quot;**Step 4: Access AureusERP**&quot;">​</a></h3><p>Open your browser and navigate to:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost</span></span></code></pre></div><p>Or use your server&#39;s IP address to access the application.</p><h3 id="step-5-login" tabindex="-1"><strong>Step 5: Login</strong> <a class="header-anchor" href="#step-5-login" aria-label="Permalink to &quot;**Step 5: Login**&quot;">​</a></h3><p>The application is pre-installed, so no setup wizard runs — go to your browser and log in using the following credentials:</p><p><strong>Admin Panel Login:</strong></p><ul><li><strong>URL:</strong> <code>http://localhost/admin</code></li><li><strong>Email:</strong> <code>admin@example.com</code></li><li><strong>Password:</strong> <code>password</code></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Change the admin password immediately after the first login. You can also bake custom credentials into a self-built image with the <code>ADMIN_NAME</code>, <code>ADMIN_EMAIL</code>, and <code>ADMIN_PASSWORD</code> build arguments.</p></div><h3 id="step-6-access-the-database-optional" tabindex="-1"><strong>Step 6: Access the Database (Optional)</strong> <a class="header-anchor" href="#step-6-access-the-database-optional" aria-label="Permalink to &quot;**Step 6: Access the Database (Optional)**&quot;">​</a></h3><p>To connect to the internal MySQL database, use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureus</span></span></code></pre></div><p>When prompted, enter the password <code>aureus</code>. The internal database name, username, and password are all <code>aureus</code> — they are baked into the image at build time. The <code>DB_DATABASE</code>, <code>DB_USERNAME</code>, and <code>DB_PASSWORD</code> environment variables only apply when connecting to an external database server.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This works only in internal-database mode. If you started the container with <code>DB_HOST</code> pointing to an external server, the internal MySQL is not running — connect to your external server instead.</p></div><p>If you need to stop the container, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp</span></span></code></pre></div><p>To restart it, use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aureuserp</span></span></code></pre></div><h2 id="getting-support" tabindex="-1">Getting Support <a class="header-anchor" href="#getting-support" aria-label="Permalink to &quot;Getting Support&quot;">​</a></h2><p>If you encounter any issues or have questions, please contact us at <code>support@aureuserp.com</code> or raise a ticket at AureusERP Support.</p><p>Your AureusERP container is now up and running! 🚀</p>`,46)]))}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
